import{c as t,Q as o,j as r,m as d}from"./chunks/framework.B1f5Gm19.js";const g=JSON.parse('{"title":"更新日志","description":"","frontmatter":{"title":"更新日志"},"headers":[],"relativePath":"developer/changelog.md","filePath":"developer/changelog.md","lastUpdated":1792683793000}'),a={name:"developer/changelog.md"};function l(i,e,n,s,c,h){return o(),r("div",null,[...e[0]||(e[0]=[d('<h2 id="v1-4-0" tabindex="-1">v1.4.0 <a class="header-anchor" href="#v1-4-0" aria-label="Permalink to &quot;v1.4.0&quot;">​</a></h2><p>发布日期：2026-10-22。REALITY 出站：客户端可直接对接 sing-box / mihomo 的 trojan-REALITY 服务端。</p><ul><li><strong>REALITY 出站</strong>：新增 <code>tunnel/reality</code> 客户端层，浏览器指纹 ClientHello 的 <code>session_id</code> 字段内嵌 x25519 ECDH + HKDF 密封的认证凭证；凭证错误时服务端透明回落真站、客户端证书校验失败报错，不暴露代理特征。<strong>零新增依赖</strong>（utls v1.8.2 + Go 标准库 hkdf）。实测对 sing-box v1.14.3 trojan-REALITY 入站端到端成功（4 路并发往返、错误 short-id/public-key 双拒）</li><li><strong>组合校验</strong>：REALITY 与 websocket、transport_plugin 互斥，配置层直接拒绝</li><li><strong>StackOptions</strong>：客户端栈组装由 5 个 bool 参数收敛为结构体（本版与 v1.2.0 的 <code>GenerateClientTree</code> 收敛为同一重构），行为零变化</li></ul><h2 id="v1-3-0" tabindex="-1">v1.3.0 <a class="header-anchor" href="#v1-3-0" aria-label="Permalink to &quot;v1.3.0&quot;">​</a></h2><p>发布日期：2026-10-22。ShadowTLS v3 服务端（头条特性）：<strong>免域名免证书的抗探测代理端口</strong>，主流客户端零定制直连。</p><ul><li><strong>tunnel/shadowtls 层</strong>：ClientHello <code>session_id</code> HMAC-SHA1 截断验签；未授权连接（含主动探测）完整中继真站握手——探测者只见真站真实证书；授权后以 ServerRandom 绑定的 HMAC/XOR 密钥劫持数据帧，内层跑裸 trojan。协议规格经 ihciah/shadow-tls（Rust 原版）、mihomo、sing-box 三方一手源码逐条交叉验证</li><li><strong>strict 模式</strong>（默认开）：真站握手非 TLS 1.3 时拒绝提供代理服务；非 strict 为 lossy 宽松模式</li><li><strong>HRR 处理 / v2 客户端回退</strong>：HelloRetryRequest 绑定首个 ServerHello；v2 客户端连接不成功但服务端不崩溃且随后 v3 仍可用</li><li><strong>utls 布局 pin 测试</strong>：<code>session_id</code> 注入依赖的 ClientHello 字节偏移由测试锁定，utls 升级破坏布局时测试即红</li><li><strong>实测</strong>：mihomo v1.19.33 与 sing-box v1.14.3 真实客户端端到端 HTTP 200（含 10 路并发）；openssl/curl 探测只见到真站证书；nginx SNI 分流共存</li><li>服务端每连接在 TLS 握手完成后释放嗅探缓冲（与 v1.2.0 的 RewindConn 优化衔接）</li></ul><h2 id="v1-2-0" tabindex="-1">v1.2.0 <a class="header-anchor" href="#v1-2-0" aria-label="Permalink to &quot;v1.2.0&quot;">​</a></h2><p>发布日期：2026-10-22。性能快赢包 + NAT 解禁。四项性能优化均为纯本地改动，<strong>线上协议字节格式零变化</strong>。</p><ul><li><strong>客户端 TLS 会话复用</strong>（修复）：<code>DialConn</code> 此前每次拨号现场新建 <code>tls.Config</code> 且从不设置 <code>ClientSessionCache</code>，<code>reuse_session</code> 配置从未生效。现共享 config + LRU 会话缓存（256），stdlib 与 utls 指纹双路径支持，握手省 1-RTT。utls 指纹路径的会话复用仅发生在 TLS 1.2（上游指纹 spec 无 PSK 扩展占位，属刻意设计，TLS 1.3 下行为与此前一致）</li><li><strong>mux 握手移出全局锁</strong>：<code>DialConn</code> 原全程持有池锁（含完整 TLS+smux 握手数百 ms），阻塞全进程新连接；现锁内只做池簿记，并发拨号实测 1002ms→502ms。慢路径建连加闸门（同一时间至多一个握手），防止空池并发风暴打出上百载波连接击穿服务端 mux 接受队列（容量 32，溢出即丢）——该回归由 TestWebsocketDetection 加压复现并已修复，守护测试固化</li><li><strong>AddTraffic 无锁快路径</strong>：未配置限速器时绕开锁只做原子累加（此前每次读写都抢读锁）；顺带修复 speedUpdater 对计数器 plain-read vs atomic-write 的既有数据竞争</li><li><strong>服务端 RewindConn 释放</strong>：TLS 嗅探完成后释放握手层缓冲，实测每连接省约 2.1KB 常驻内存（50k 连接约 150MB→~6MB），嗅探分流行为字节级不变并由回归测试锁定</li><li><strong>NAT 模式解禁 router</strong>：移除上游历史遗留的禁用守卫（网关 PREROUTING 形态无回环风险）；域名规则在 DNS 未劫持时受限，见透明代理文档</li><li><strong>其他</strong>：trojan 客户端头部延迟 flush 由不可取消 Sleep 改为可取消等待；mux 池清理日志降噪</li></ul><h2 id="v1-1-2" tabindex="-1">v1.1.2 <a class="header-anchor" href="#v1-1-2" aria-label="Permalink to &quot;v1.1.2&quot;">​</a></h2><p>发布日期：2026-10-22。P2 可靠性收尾修复：错误链穿透、TLS 会话恢复、客户端 ALPN。</p><ul><li><strong>错误链</strong>：<code>common.Error</code> 此前仅拼接错误字符串（被包装的 error 对象被丢弃），现保存 cause 并实现 <code>Unwrap()</code>——<code>errors.Is/As</code> 可穿透整个包装链，<code>Error()</code> 输出格式不变。<code>proxy</code> 与 <code>transport</code> 中两处字符串后缀匹配的临时方案退化为精确的 <code>errors.Is</code> 判断</li><li><strong>TLS 服务端</strong>：tls.Config 改为全连接共享（原实现每连接新建）。session ticket key 存于 Config 实例内部，逐连接配置使每个 ticket 只在单个连接内有效，<strong>会话恢复（session resumption）从未生效</strong>；修复后 <code>reuse_session</code> 配置真正兑现，减少全量握手的 1-RTT 与非对称运算开销。附跨连接恢复的回归测试（变异验证：逐连接配置下必红）</li><li><strong>TLS 客户端</strong>：utls 与标准库两条路径均传递 ALPN（<code>NextProtos</code>），缺省 <code>http/1.1</code>（WebSocket 依赖 HTTP/1.1，避免协商出 h2 破坏握手）。utls 指纹路径此前完全忽略 ALPN——真实浏览器 ClientHello 必带该扩展，伪装指纹缺失 ALPN 本身即指纹矛盾点。cipher/session 在指纹路径仍被有意忽略（指纹固定语义，非缺陷）</li></ul><h2 id="v1-1-1" tabindex="-1">v1.1.1 <a class="header-anchor" href="#v1-1-1" aria-label="Permalink to &quot;v1.1.1&quot;">​</a></h2><p>发布日期：2026-10-22。入站链可靠性修复：消除「新连接全挂、既有连接正常、进程存活、只能重启」类故障的全部已知代码级成因。每项修复均附经变异验证的回归测试（对旧代码必红）。</p><h3 id="p0-—-可致服务整体不可用" tabindex="-1">P0 — 可致服务整体不可用 <a class="header-anchor" href="#p0-—-可致服务整体不可用" aria-label="Permalink to &quot;P0 — 可致服务整体不可用&quot;">​</a></h3><table tabindex="0"><thead><tr><th>修复项</th><th>缺陷</th><th>后果</th></tr></thead><tbody><tr><td>transport accept 容错</td><td>对任意 Accept 错误（含瞬时 EMFILE/ENFILE）log 后直接 return，<strong>永久停止 accept</strong></td><td>fd 压力波动一次即触发「端口在听但新连接无人接收」，不可自愈。现仅 <code>net.ErrClosed</code>/ctx 退出，其余指数退避（5ms→1s）持续重试</td></tr><tr><td>TLS 入站链 deadline</td><td>每连接 goroutine 全程零 SetDeadline</td><td>建连后不发（或半发）ClientHello 的静默连接<strong>永久</strong>占用 goroutine。现握手与请求解析各设 30s 超时，协议识别后清除</td></tr><tr><td>裸 channel 发送</td><td><code>connChan</code>/<code>wsChan</code>（容量 32）无 ctx 保护发送</td><td>下游停滞时每个新连接的 goroutine 持 fd 阻塞堆积直至 EMFILE。现 <code>select</code>+<code>ctx.Done()</code>，退出路径关连接</td></tr><tr><td>WebSocket 畸形请求卡滞</td><td>带 Upgrade 头但缺 <code>Sec-WebSocket-Key</code> 的请求使 x/net/websocket 静默返回，AcceptConn 必等满随机 5-15s 超时</td><td>上层串行调用，低速率恶意流即可长期占死 ws 接受路径并级联 fd 堆积。现 ServeHTTP 任意退出立即解除等待</td></tr><tr><td>simplesocks 串行读头</td><td>acceptLoop 串行对每条 smux 流读协议头，无超时</td><td>一条开流不发头的连接卡死全部新 mux 流。现 per-stream goroutine 化（不用 SetDeadline——deadline 会透传杀死整个 smux 会话）</td></tr></tbody></table><h3 id="p1-—-资源与噪音" tabindex="-1">P1 — 资源与噪音 <a class="header-anchor" href="#p1-—-资源与噪音" aria-label="Permalink to &quot;P1 — 资源与噪音&quot;">​</a></h3><table tabindex="0"><thead><tr><th>修复项</th><th>缺陷</th></tr></thead><tbody><tr><td>checkKeyPairLoop busy-loop</td><td>证书文件暂时不可读（acme.sh 替换窗口/挂载抖动）时三个 error 分支的 <code>continue</code> 跳过 ticker 等待，无间隔自旋烧满一个核+日志刷屏。实测旧代码 225ms 内重试 125,894 次，修复后受 checkRate 节流</td></tr><tr><td>UDP 会话关闭误报</td><td>trojan UDP 会话无显式拆链消息，客户端关连接产生的 io.EOF 被当 ERROR 高频刷屏。EOF/ErrClosed/ECONNRESET 降为 debug，<code>unexpected EOF</code>（截断帧，真异常）仍报 ERROR</td></tr><tr><td>ws 超时路径泄漏</td><td>握手超时后连接不关闭、Handler goroutine 阻塞在无缓冲 channel。现 chan 缓冲 1 + 超时关连接</td></tr></tbody></table><h3 id="构建" tabindex="-1">构建 <a class="header-anchor" href="#构建" aria-label="Permalink to &quot;构建&quot;">​</a></h3><ul><li>Dockerfile builder 升级 golang:1.26-alpine（go.mod 已要求 1.26.0）</li><li>新增 <code>Dockerfile.runtime</code>：本地交叉编译二进制+geo 数据直接打包的轻量运行时镜像（完整多阶段构建需在容器内拉取私有依赖，无凭证不可行）</li><li>scenario 集成测试的内联证书改为运行时自签（原证书 2026-09-13 过期导致全量测试必红）</li></ul><h2 id="v1-1-0" tabindex="-1">v1.1.0 <a class="header-anchor" href="#v1-1-0" aria-label="Permalink to &quot;v1.1.0&quot;">​</a></h2><p>发布日期：2026-10-11。反向端口转发与反 DPI 指纹能力。</p><h3 id="新特性" tabindex="-1">新特性 <a class="header-anchor" href="#新特性" aria-label="Permalink to &quot;新特性&quot;">​</a></h3><ul><li><strong>reverse 反向端口转发</strong>：新增 <code>tunnel/reverse</code> 包与控制协议（trojan 命令字 Reverse/4），支持服务端反向穿透客户端侧端口；<code>ReverseListener</code> 暴露 <code>Connected()</code> 会话健康面，供上层换路看门狗区分「隧道活着但上级僵死」与正常瞬断；流级闲置掐断（<code>stream_idle_timeout</code>）与 session 健康检测解耦；附进程内全链路测试（回显/ACL/冲突/重连/泄漏）</li><li><strong>smux 帧级随机化（反 DPI）</strong>：帧切分点从 <code>[frame_min, frame_max]</code> 均匀随机（默认关闭），打破固定分片→固定 TLS record 周期的可统计指纹；keepalive NOP 间隔 ±jitter 随机（默认关闭）打散固定周期信标。线上协议零改动，旧对端照常解析</li><li><strong>TLS 客户端证书指纹钉死</strong>（<code>cert_pin_sha256</code>）：握手后校验叶子证书 SHA-256，支持冒号分组与裸 hex。级联叶子连自签跳板时比裸关校验安全</li></ul><h3 id="修复" tabindex="-1">修复 <a class="header-anchor" href="#修复" aria-label="Permalink to &quot;修复&quot;">​</a></h3><ul><li>reverse bind 握手超时 10s→30s（高负载下测试 1/10 复现误判）</li><li>reverse 配置遵循 trojan-go 顶层节约定</li><li>测试硬编码证书全量换运行时自签（2026-09-13 过期）</li></ul><h3 id="依赖" tabindex="-1">依赖 <a class="header-anchor" href="#依赖" aria-label="Permalink to &quot;依赖&quot;">​</a></h3><p>合并 Dependabot 累积 PR：grpc 1.83.2、x/net 0.59.0、protobuf 1.36.12、mysql 1.10.1、testify 1.12.1 等</p><h2 id="v1-0-2" tabindex="-1">v1.0.2 <a class="header-anchor" href="#v1-0-2" aria-label="Permalink to &quot;v1.0.2&quot;">​</a></h2><p>发布日期：2026-06-30。CI/CD 基础设施维护与依赖升级，无功能性变更，对终端用户无感知。</p><h3 id="ci-cd-修复" tabindex="-1">CI/CD 修复 <a class="header-anchor" href="#ci-cd-修复" aria-label="Permalink to &quot;CI/CD 修复&quot;">​</a></h3><ul><li>修复 <code>dependabot-auto-merge</code> 工作流在 <strong>major 版本更新</strong>时误报失败的问题：根因是 <code>pull_request_target</code> 事件无 checkout 步骤，<code>gh label create</code> 缺少 <code>--repo</code> 上下文导致找不到 git 仓库；修复方式为注入 <code>GH_REPO</code> 环境变量，并对 major 通知步骤增加 <code>continue-on-error</code> 容错</li><li>合并 Dependabot 累积的依赖更新 PR（#1 checkout、#2 action-gh-release、#3 setup-go、#9 golang.org/x/net）</li></ul><h3 id="依赖升级" tabindex="-1">依赖升级 <a class="header-anchor" href="#依赖升级" aria-label="Permalink to &quot;依赖升级&quot;">​</a></h3><table tabindex="0"><thead><tr><th>依赖</th><th>旧版本</th><th>新版本</th><th>类型</th></tr></thead><tbody><tr><td>actions/checkout</td><td>v4</td><td>v6</td><td>major</td></tr><tr><td>actions/setup-go</td><td>v5</td><td>v6</td><td>major</td></tr><tr><td>softprops/action-gh-release</td><td>v2</td><td>v3</td><td>major</td></tr><tr><td>golang.org/x/net</td><td>0.55.0</td><td>0.56.0</td><td>minor</td></tr></tbody></table><h2 id="v1-0-1" tabindex="-1">v1.0.1 <a class="header-anchor" href="#v1-0-1" aria-label="Permalink to &quot;v1.0.1&quot;">​</a></h2><p>发布日期：2026-06-08。TLS 与 smux 稳定性修复。</p><ul><li><strong>TLS</strong>：证书加载错误信息补全（上游 Issue #513）</li><li><strong>smux</strong>：<code>stickyConn</code> 改为非阻塞发送，防止 channel 满时 goroutine 死锁</li><li><strong>兼容性</strong>：处理 <code>x509.DecryptPEMBlock</code> 在新版 Go 中的废弃警告</li><li><strong>CI</strong>：修复 golangci-lint 配置与 shadowsocks 测试超时问题</li></ul><h2 id="v1-0-0" tabindex="-1">v1.0.0 <a class="header-anchor" href="#v1-0-0" aria-label="Permalink to &quot;v1.0.0&quot;">​</a></h2><p>初始正式发布版本。基于 <code>0.10.6-bugfix</code> 稳定基线，确立语义化版本号（SemVer）体系与完整的 CI/CD 流水线（Test、Linter、Docker 多架构构建、nightly 构建、自动发布）。详细变更请参见下方 <code>0.10.6-bugfix</code> 的完整明细。</p><h2 id="_0-10-6-bugfix" tabindex="-1">0.10.6-bugfix <a class="header-anchor" href="#_0-10-6-bugfix" aria-label="Permalink to &quot;0.10.6-bugfix&quot;">​</a></h2><p>本次更新基于 p4gefau1t/trojan-go-next v0.10.6，精选了安全性和稳定性修复。仅修 bug，不加功能，不改架构。</p><p>项目现由 <a href="https://github.com/corevx" target="_blank" rel="noreferrer">corevx</a> 维护，仓库迁移至 <a href="https://github.com/corevx/trojan-go-next" target="_blank" rel="noreferrer">corevx/trojan-go-next</a>。</p><h3 id="重要变更" tabindex="-1">重要变更 <a class="header-anchor" href="#重要变更" aria-label="Permalink to &quot;重要变更&quot;">​</a></h3><ul><li>Go 版本要求从 <strong>1.14</strong> 提升至 <strong>1.22</strong></li><li>所有 <code>io/ioutil</code> 调用已迁移至 <code>io</code> 和 <code>os</code> 包（Go 1.16+ 推荐做法）</li><li>新增 Docker 多阶段构建支持</li></ul><h3 id="安全性修复" tabindex="-1">安全性修复 <a class="header-anchor" href="#安全性修复" aria-label="Permalink to &quot;安全性修复&quot;">​</a></h3><table tabindex="0"><thead><tr><th>修复项</th><th>影响范围</th><th>详情</th></tr></thead><tbody><tr><td>加密私钥加载</td><td>服务端</td><td>修复 <code>x509.DecryptPEMBlock</code> 在 Go 1.22+ 不可用的问题，恢复加密私钥支持</td></tr><tr><td>私钥解密逻辑反转</td><td>服务端</td><td>原代码在解密成功时返回错误，导致加密私钥始终无法使用。现在解密失败时才报错</td></tr><tr><td>MySQL 用户删除</td><td>MySQL 模式</td><td><code>RowsAffected</code> 逻辑反转：原代码在 <code>err != nil</code> 时检查结果，现已修正为 <code>err == nil &amp;&amp; r == 0</code>。修复删除用户后仍可连接的问题（Issue #374）</td></tr></tbody></table><h3 id="稳定性修复" tabindex="-1">稳定性修复 <a class="header-anchor" href="#稳定性修复" aria-label="Permalink to &quot;稳定性修复&quot;">​</a></h3><table tabindex="0"><thead><tr><th>修复项</th><th>影响范围</th><th>详情</th></tr></thead><tbody><tr><td>Panic 恢复</td><td>服务端</td><td>在 trojan/tls/mux 三个 server 的连接处理 goroutine 中添加 <code>defer recover()</code>，防止单连接 panic 导致整个服务崩溃</td></tr><tr><td>非阻塞 Channel 发送</td><td>服务端</td><td>trojan/server.go 中 4 处 channel 发送改为 <code>select</code> 非阻塞模式，防止 channel 满时 goroutine 永久阻塞</td></tr><tr><td>Ticker 泄漏</td><td>服务端</td><td>tls/server.go <code>checkKeyPairLoop</code> 和 memory.go <code>speedUpdater</code> 中添加 <code>defer ticker.Stop()</code>，防止 goroutine 泄漏</td></tr></tbody></table><h3 id="功能性修复" tabindex="-1">功能性修复 <a class="header-anchor" href="#功能性修复" aria-label="Permalink to &quot;功能性修复&quot;">​</a></h3><table tabindex="0"><thead><tr><th>修复项</th><th>影响范围</th><th>详情</th></tr></thead><tbody><tr><td>限速 bug</td><td>API + 服务端</td><td>memory.go 中 <code>else if</code> 改为 <code>if</code>，使 recv 限速器独立于 send 限速器运行。修复通过 API 设定的限速不生效的问题（Issue #216）</td></tr><tr><td>SNI 错误消息</td><td>服务端</td><td>SNI 校验失败时的错误消息现在会显示证书的 DNSNames 列表，而不仅显示硬编码的 sni 字段，方便排查（Issue #531, PR #532）</td></tr></tbody></table><h3 id="性能优化" tabindex="-1">性能优化 <a class="header-anchor" href="#性能优化" aria-label="Permalink to &quot;性能优化&quot;">​</a></h3><table tabindex="0"><thead><tr><th>优化项</th><th>影响范围</th><th>详情</th></tr></thead><tbody><tr><td>sync.Pool</td><td>全局</td><td>proxy/proxy.go 中 UDP 包缓冲区使用 <code>sync.Pool</code> 复用，减少高频场景下的内存分配和 GC 压力</td></tr></tbody></table><h3 id="明确不包含的改动" tabindex="-1">明确不包含的改动 <a class="header-anchor" href="#明确不包含的改动" aria-label="Permalink to &quot;明确不包含的改动&quot;">​</a></h3><p>以下改动来自社区 fork，经评估存在破坏性，<strong>未合并</strong>：</p><ul><li><s>30s 硬编码超时</s> — 导致客户端 38 秒固定断流（Issue #73）</li><li><s>net.Dial 替换 underlay.DialConn</s> — 破坏隧道栈分层，WebSocket+TLS 失效</li><li><s>QUIC 隧道</s> — 新功能，非 bug fix</li><li><s>SQLite 持久化</s> — 新功能，依赖 CGO</li><li><s>Recorder 模块</s> — 新功能</li><li><s>X-Forwarded-For 注入</s> — 新功能</li></ul><h3 id="验证状态" tabindex="-1">验证状态 <a class="header-anchor" href="#验证状态" aria-label="Permalink to &quot;验证状态&quot;">​</a></h3><ul><li>编译：<code>make clean &amp;&amp; make</code> 通过</li><li>单元测试：24 个测试包全部通过（<code>go test -v ./...</code>）</li><li>集成测试：server + client SOCKS5 代理 HTTP 流量验证通过</li></ul>',57)])])}const b=t(a,[["render",l]]);export{g as __pageData,b as default};
